import { ScopeHooks } from "sockapi/scope-specs";
import { ScopeType } from "sockapi/scope-types";

/**
 * A character on the VN cutscene stage for a keyframe. This is the resolved
 * form: `update-keyframes` has already turned the author's `pan:distressed`
 * shorthand into a display name, color, and sprite image name.
 */
export type KeyframeStageCharacter = {
  /** Stable id, used to match against `speaker`. */
  characterId: string;
  /** Display name for the name plate. */
  name: string;
  /** Name-plate accent color (any CSS color). */
  color?: string;
  /** Path under /static/images/. */
  imageName: string;
  /** Horizontally flip the sprite (e.g. to face inward). */
  flip?: boolean;
};

export const BGM_VARIANTS = ["ambient", "full"] as const;

export type KeyframeData = {
  puzName: string;
  endCutscene?: boolean;
  /** Empty for a beat with no dialogue box (dialogue `-` in the sheet). */
  dialogue: string;
  dialogOptions?: string[];
  nextId: string[];
  /** Path under /static/images/; absent shows the default cafe background. */
  background?: string;
  /** VN cutscene stage, in left-to-right order. */
  stage?: KeyframeStageCharacter[];
  /** `characterId` of whoever is speaking this line (for name plate + spotlight). */
  speaker?: string;
  /** Narration rather than a spoken line (speaker `-` in the sheet); no speaker. */
  stageDirection?: true;
  /** Path to redirect to when the cutscene is complete, if any. */
  redirectPath?: string;
  /**
   * If set, the team would not be allowed to access this keyframe
   * unless the condition is satisfied. Conditions must be manually
   * implemented.
   */
  keyframeReq?: string;
  /**
   * If set, the dialog options would respectively be displayed as
   * disabled if their respective conditions are not satisfied.
   */
  dialogOptionsReqs?: string[];
  bgm: null | (typeof BGM_VARIANTS)[number];
  isCg?: true;
  /** SFX sprite id (e.g. `old-ringtone`) played once when this line starts. */
  sfx?: string;
};

/** A set of keyframes keyed by keyframe id (e.g. one cutscene's frames). */
export type KeyframesById = { [keyframeId: string]: KeyframeData };

export type KeyframeScopeSpec = {
  identifier: { keyframeId: string };
  state: KeyframeData;
};

export const keyframeScopeHooks: ScopeHooks<ScopeType.KEYFRAME> = {
  identityFunc: (scope) => scope,
  getIdComponents: ({ keyframeId }) => [keyframeId],
};
