import {
  MYOCBAxis as Axis,
  MYOCBLine as Line,
} from "sockapi/scope-specs/team-myocb-spec";

const ROW: Axis = 0; // Albert
const COL: Axis = 1; // Bernard

/** A candidate set, held as "r,c" keys. */
export type State = ReadonlySet<string>;

export const key = (r: number, c: number): string => `${r},${c}`;
export const parse = (k: string): { r: number; c: number } => {
  const [r, c] = k.split(",").map(Number);
  return { r, c };
};

const coord = (k: string, ax: Axis): number =>
  ax === ROW
    ? Number(k.slice(0, k.indexOf(",")))
    : Number(k.slice(k.indexOf(",") + 1));

function counts(S: State, ax: Axis): Map<number, number> {
  const m = new Map<number, number>();
  for (const k of S) {
    const v = coord(k, ax);
    m.set(v, (m.get(v) ?? 0) + 1);
  }
  return m;
}

function lines(S: State, ax: Axis): Map<number, string[]> {
  const m = new Map<number, string[]>();
  for (const k of S) {
    const v = coord(k, ax);
    const cur = m.get(v);
    if (cur) cur.push(k);
    else m.set(v, [k]);
  }
  return m;
}

/**
 * Apply one line to `S`.  `prev` is the candidate set before the previous
 * line, needed by "before"; for the first line, pass `S` itself.
 */
function step(S: State, line: Line, prev: State): Set<string> {
  const a = line.speaker;
  const o: Axis = a === ROW ? COL : ROW;
  const ca = counts(S, a),
    co = counts(S, o);
  const keep = (pred: (k: string) => boolean): Set<string> => {
    const out = new Set<string>();
    for (const k of S) if (pred(k)) out.add(k);
    return out;
  };
  const keepLines = (ok: (cells: string[]) => boolean): Set<string> => {
    const good = new Set<number>();
    for (const [L, cells] of lines(S, a)) if (ok(cells)) good.add(L);
    return keep((k) => good.has(coord(k, a)));
  };

  switch (line.kind) {
    // delete every one of my lines holding exactly one candidate
    case "dont_know":
      return keep((k) => (ca.get(coord(k, a)) ?? 0) >= 2);
    // keep only my lines holding exactly one candidate
    case "know":
      return keep((k) => ca.get(coord(k, a)) === 1);
    // I know you don't know: delete my lines touching a singleton line of yours
    case "kod": {
      const bad = new Set<number>();
      for (const k of S) if (co.get(coord(k, o)) === 1) bad.add(coord(k, a));
      return keep((k) => !bad.has(coord(k, a)));
    }
    // I don't know whether you know: keep my lines touching both a singleton
    // line of yours and a larger one
    case "dkw":
      return keepLines(
        (cells) =>
          cells.some((k) => co.get(coord(k, o)) === 1) &&
          cells.some((k) => (co.get(coord(k, o)) ?? 0) > 1)
      );
    // Empty unless the previous line was the other speaker's: my own lines
    // delete whole lines of mine, so they never change whether I know.
    case "before": {
      const cp = counts(prev, a);
      return keep(
        (k) => ca.get(coord(k, a)) === 1 && (cp.get(coord(k, a)) ?? 0) >= 2
      );
    }
    // if you said you didn't know, I would know
    case "ifdk":
      return keepLines(
        (cells) =>
          cells.filter((k) => (co.get(coord(k, o)) ?? 0) > 1).length <= 1
      );
  }
}

export function run(
  grid: State,
  transcript: readonly Line[]
): {
  /** Cells still consistent with the whole transcript. */
  answer: Set<string>;
  /** Index of the line that emptied the grid, or null if it survived. */
  deadAt: number | null;
  /** Candidates before the first line, then after each line run. */
  states: Set<string>[];
} {
  const states: Set<string>[] = [new Set(grid)];
  let S: Set<string> = new Set(grid);
  for (let i = 0; i < transcript.length; i++) {
    S = step(S, transcript[i], states[Math.max(i - 1, 0)]);
    states.push(S);
    if (S.size === 0) return { answer: new Set(), deadAt: i, states };
  }
  return { answer: S, deadAt: null, states };
}

/** Reject a submission before running it.  Returns null when it is legal. */
export function validate(transcript: readonly Line[]): string | null {
  if (transcript.length === 0) return "The puzzle is empty.";
  for (let i = 0; i < transcript.length; i++) {
    const l = transcript[i];
    if (l.kind !== "before") continue;
    const you = l.speaker === ROW ? "Bernard" : "Albert";
    if (i === 0 || transcript[i - 1].speaker === l.speaker)
      return `Line ${i + 1} must come right after a line by ${you}.`;
  }
  return null;
}
