import { ScopeHooks } from "sockapi/scope-specs";
import { SockAPIScopeState } from "sockapi/scope-state";
import { getTeamScopeIdComponents } from "sockapi/scope-specs-util";
import { ScopeType } from "sockapi/scope-types";
import { ScopeTeamIdentifier } from "sockapi/scopes";

export const VOWELS_CONFIG = {
  puzName: "472bb0e8",
  maxFileSize: 10e6,
  supportedExtensions: [".mp3", ".wav", ".m4a", ".ogg"],
};

export enum VowelsStatusType {
  PENDING = "pending",
  ACCEPTED = "accepted",
  REJECTED = "rejected",
}

export type VowelsReview =
  | { type: VowelsStatusType.ACCEPTED; comment?: string }
  | { type: VowelsStatusType.REJECTED; reason: string };

export type VowelsStatus = { submitTime: number } & (
  | { type: VowelsStatusType.PENDING }
  | (VowelsReview & {
      reviewTime: number;
    })
);

export const isTeamVowelsEditable = ({
  status,
}: SockAPIScopeState<ScopeType.TEAM_VOWELS>) =>
  status === undefined || status.type === VowelsStatusType.REJECTED;

export type TeamVowelsScopeSpec = {
  identifier: ScopeTeamIdentifier;
  state: {
    audioUrl?: string;
    status?: VowelsStatus;
  };
  update: {
    audioUrl?: string;
    status?: VowelsStatus;
  };
  step: {
    downloadAudioUrl?: true;
    submit?: true;
    review?: VowelsReview;
  };
  stepResponse: "";
  backendState: SockAPIScopeState<ScopeType.TEAM_VOWELS>;
};

export const teamVowelsScopeHooks: ScopeHooks<ScopeType.TEAM_VOWELS> = {
  identityFunc: (scope) => scope,
  getIdComponents: getTeamScopeIdComponents,
  update: (scopeState, payload) => {
    const { audioUrl, status } = payload;
    if (audioUrl !== undefined) scopeState.audioUrl = audioUrl;
    if (status !== undefined) scopeState.status = status;
  },
};
