import { ScopeHooks } from "sockapi/scope-specs";
import { getTeamScopeIdComponents } from "sockapi/scope-specs-util";
import { ScopeType } from "sockapi/scope-types";
import { ScopeTeamIdentifier } from "sockapi/scopes";

export const GRID_ADVENTURE_CONFIG = {
  puzName: "835f7685",
  numCells: 21 * 21,
  /** In code points, to allow short rebuses. */
  maxCellLength: 8,
};

export const isValidGridAdventureCell = (value: string) =>
  [...value].length <= GRID_ADVENTURE_CONFIG.maxCellLength &&
  !/\p{Cc}/u.test(value);

/** [cell index (row-major), value]; "" clears the cell. */
export type GridAdventureCellEdit = [number, string];

export type TeamGridAdventureScopeSpec = {
  identifier: ScopeTeamIdentifier;
  /** `cells[i]` is cell i's value; "" is empty. */
  state: { cells: string[] };
  update: { set: GridAdventureCellEdit[] };
  step: { set: GridAdventureCellEdit[] };
  stepResponse: "";
  backendState: { cells: string[] };
};

export const teamGridAdventureScopeHooks: ScopeHooks<ScopeType.TEAM_GRID_ADVENTURE> =
  {
    identityFunc: (scope) => scope,
    getIdComponents: getTeamScopeIdComponents,
    update: (scopeState, payload) => {
      for (const [i, value] of payload.set) scopeState.cells[i] = value;
    },
  };
