import { ScopeHooks } from "sockapi/scope-specs";
import { getPuzzleScopeIdComponents } from "sockapi/scope-specs-util";
import { ScopeType } from "sockapi/scope-types";
import { ScopePuzzleIdentifier } from "sockapi/scopes";
import { KeyframesById } from "sockapi/scope-specs/keyframe-spec";

export type RawPuzzleContent = {
  hash: string;
  content: string;
};

export enum PuzzleContentType {
  PUZZLE = "puzzle",
  STORY = "story",
  SOLUTION = "solution",
}

export type ContentfulPuzzleContentType =
  | PuzzleContentType.PUZZLE
  | PuzzleContentType.SOLUTION;

export type PuzzlePuzzleContent = {
  type: PuzzleContentType.PUZZLE;
} & RawPuzzleContent;

export type StoryPuzzleContent = {
  type: PuzzleContentType.STORY;
  firstKeyframeId: string;
  bgm: string | null;
  keyframes: KeyframesById;
};

export type SolutionPuzzleContent = {
  type: PuzzleContentType.SOLUTION;
  answer: string | null;
  authors: string[];
  otherCredits?: string;
} & RawPuzzleContent;

export type FullPuzzleContent =
  | PuzzlePuzzleContent
  | StoryPuzzleContent
  | SolutionPuzzleContent;

export const arePuzzleContentEqual = (
  a?: FullPuzzleContent,
  b?: FullPuzzleContent
): boolean => {
  if (a === undefined || b === undefined)
    return a === undefined && b === undefined;
  for (const key in a) if (!(key in b)) return false;
  for (const key in b) {
    if (!(key in a)) return false;
    if (
      JSON.stringify(a[key as keyof typeof a]) !==
      JSON.stringify(b[key as keyof typeof b])
    )
      return false;
  }
  return true;
};

export const getPuzzleContentStaticDir = (content: RawPuzzleContent): string =>
  `/static/puzzle_resources/${content.hash}`;

export type PuzzleContentScopeSpec = {
  identifier: ScopePuzzleIdentifier;
  state: PuzzlePuzzleContent | StoryPuzzleContent;
};

export const puzzleContentScopeHooks: ScopeHooks<ScopeType.PUZZLE_CONTENT> = {
  identityFunc: (scope) => scope,
  getIdComponents: getPuzzleScopeIdComponents,
};
