import { ScopeHooks } from "sockapi/scope-specs";
import { getPuzzleScopeIdComponents } from "sockapi/scope-specs-util";
import { ScopeType } from "sockapi/scope-types";
import { ScopePuzzleIdentifier } from "sockapi/scopes";

/** One line of post-solve dialogue, as stored in solve-dialogue.json. */
export type SolveDialogueEntry = {
  // Character id, which is also their round id (e.g. "camille")
  characterId: string;
  // Which cutscene sprite to use (e.g. "thinking")
  sprite?: string;
  dialogue: string;
};

/** A line with the character's name and color filled in, as sent to clients. */
export type SolveDialogueLine = SolveDialogueEntry & {
  name: string;
  color?: string;
  // Sprite image path, shown in place of the portrait while this is the speaker's latest line
  imageName?: string;
  // Mirror the sprite, as the cutscene stage would
  flip?: boolean;
};

/** Path to a character's cutscene sprite, under /static/images/. */
export const solveDialogueSpriteName = (sprite: string): string =>
  `cutscenes/${sprite}.webp`;

export type SolveDialogueScopeSpec = {
  identifier: ScopePuzzleIdentifier;
  state: {
    // Empty if the puzzle has no dialogue
    lines: SolveDialogueLine[];
    // The cutscene solving this unlocks (a meta's postmeta), to replay instead
    cutscene?: { puzName: string; slug: string };
  };
};

export const solveDialogueScopeHooks: ScopeHooks<ScopeType.SOLVE_DIALOGUE> = {
  identityFunc: (scope) => scope,
  getIdComponents: getPuzzleScopeIdComponents,
};
