import { ScopeHooks } from "sockapi/scope-specs";
import { getTeamScopeIdComponents } from "sockapi/scope-specs-util";
import { ScopeType } from "sockapi/scope-types";
import { ScopeTeamIdentifier } from "sockapi/scopes";

/**
 * Remove id from whichever day it's in, then insert it into days[day] before
 * beforeId, or at the end of that day if beforeId is null or no longer there.
 */
export type MetametaMove = [id: string, day: number, beforeId: string | null];

export const applyMetametaMove = (
  days: string[][],
  [id, day, beforeId]: MetametaMove
): void => {
  for (const ids of days) {
    const i = ids.indexOf(id);
    if (i !== -1) ids.splice(i, 1);
  }
  const target = days[day];
  const at = beforeId === null ? -1 : target.indexOf(beforeId);
  target.splice(at === -1 ? target.length : at, 0, id);
};

export type TeamMetametaScopeSpec = {
  identifier: ScopeTeamIdentifier;
  /** puzNames, grouped by day, in draft order */
  state: { days: string[][] };
  update: { move: MetametaMove };
  step: { move: MetametaMove } | { submit: true };
  stepResponse: { correct?: boolean; isRateLimited?: true };
  /** days is optional so drafts saved in an old shape still validate */
  backendState: { days?: string[][] };
};

export const teamMetametaScopeHooks: ScopeHooks<ScopeType.TEAM_METAMETA> = {
  identityFunc: (scope) => scope,
  getIdComponents: getTeamScopeIdComponents,
  update: (scopeState, payload) => {
    applyMetametaMove(scopeState.days, payload.move);
  },
};
