import { ScopeHooks } from "sockapi/scope-specs";
import { getTeamScopeIdComponents } from "sockapi/scope-specs-util";
import { ScopeType } from "sockapi/scope-types";
import { ScopeTeamIdentifier } from "sockapi/scopes";

// 0 = Albert (row), 1 = Bernard (column)
export type MYOCBAxis = 0 | 1;

export type MYOCBLineKind =
  | "dont_know"
  | "know"
  | "kod"
  | "dkw"
  | "before"
  | "ifdk";

export type MYOCBLine = {
  kind: MYOCBLineKind;
  speaker: MYOCBAxis;
};

export const MYOCB_CONFIG: {
  puzName: string;
  mask: string[];
  kinds: Omit<MYOCBLine, "speaker">[];
  maxLines: number;
} = {
  puzName: "00a73507",
  mask: [
    "..x..x..",
    "...x..x.",
    ".x.x....",
    "..x...x.",
    "x....x.x",
    "....x..x",
    "....x...",
    "...x....",
  ],
  kinds: [
    { kind: "dont_know" },
    { kind: "know" },
    { kind: "kod" },
    { kind: "dkw" },
    { kind: "before" },
    { kind: "ifdk" },
  ],
  maxLines: 50,
};

export const describeMYOCBLine = (
  line: MYOCBLine,
  /** Drop the `Albert: ` prefix, for when the speaker is shown separately. */
  omitSpeaker = false
): string => {
  const me = line.speaker === 0 ? "Albert" : "Bernard";
  const you = line.speaker === 0 ? "Bernard" : "Albert";
  const says = (() => {
    switch (line.kind) {
      case "dont_know":
        return `I don't know the location.`;
      case "know":
        return `I know the location.`;
      case "kod":
        return `I know that ${you} doesn't know the location.`;
      case "dkw":
        return `I don't know whether ${you} knows the location.`;
      case "before":
        return `Before ${you} said that, I didn't know the location, but I know now.`;
      case "ifdk":
        return `If ${you} said he didn't know, I would know the location.`;
    }
  })();
  return omitSpeaker ? says : `${me}: ${says}`;
};

export type TeamMYOCBScopeSpec = {
  identifier: ScopeTeamIdentifier;
  step: { transcript: MYOCBLine[] };
  stepResponse: {
    status: "ok" | "warn" | "error";
    message: string;
  };
};

export const teamMYOCBScopeHooks: ScopeHooks<ScopeType.TEAM_MYOCB> = {
  identityFunc: (scope) => scope,
  getIdComponents: getTeamScopeIdComponents,
};
