import { ScopeHooks } from "sockapi/scope-specs";
import { getTeamScopeIdComponents } from "sockapi/scope-specs-util";
import { ScopeType } from "sockapi/scope-types";
import { ScopeTeamIdentifier } from "sockapi/scopes";

export const WORDTRIS_CONFIG = {
  puzName: "8d32de1d",
  numPieces: 35,
  cellsPerPiece: 4,
  numGrids: 5,
  rows: 6,
  cols: 5,
};

export const isValidWordtrisLetter = (value: string) =>
  [...value].length <= 1 && !/\p{Cc}/u.test(value);

/**
 * Quarter turns clockwise from the MDX orientation; (row, col) is the top-left
 * of the rotated bounding box.
 */
export type WordtrisPlacement = {
  grid: number;
  row: number;
  col: number;
  rot: 0 | 1 | 2 | 3;
};

export type WordtrisUpdate = {
  /** [piece * 4 + cell in MDX reading order, value]; "" clears it. */
  letters?: [number, string][];
  /** [piece, placement]; null takes it off the board. */
  place?: [number, WordtrisPlacement | null][];
};

export type TeamWordtrisScopeSpec = {
  identifier: ScopeTeamIdentifier;
  state: {
    /** Indexed like `WordtrisUpdate.letters`; "" is empty. */
    letters: string[];
    placements: (WordtrisPlacement | null)[];
  };
  update: WordtrisUpdate;
  step: WordtrisUpdate;
  stepResponse: "";
  backendState: {
    letters: string[];
    placements: (WordtrisPlacement | null)[];
  };
};

export const teamWordtrisScopeHooks: ScopeHooks<ScopeType.TEAM_WORDTRIS> = {
  identityFunc: (scope) => scope,
  getIdComponents: getTeamScopeIdComponents,
  update: (scopeState, payload) => {
    for (const [i, value] of payload.letters ?? [])
      scopeState.letters[i] = value;
    for (const [p, placement] of payload.place ?? [])
      scopeState.placements[p] = placement;
  },
};
